CREATE TABLE `content_blocks` (
	`id` text PRIMARY KEY NOT NULL,
	`label` text NOT NULL,
	`draft_fields` text NOT NULL,
	`published_fields` text,
	`updated_by_name` text NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	`published_at` integer
);

-- Seed sensible defaults matching the site's existing real copy (not
-- fabricated content) so pages don't regress to empty before an admin
-- edits anything. Published immediately since this text is already live.
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('homepage-hero', 'Homepage Hero', '{"title":"Central Moon Sighting Committee","description":"Official moon-sighting announcements, reports and Islamic calendar information for communities across Great Britain and Europe."}', '{"title":"Central Moon Sighting Committee","description":"Official moon-sighting announcements, reports and Islamic calendar information for communities across Great Britain and Europe."}', 'System', unixepoch());
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('footer-text', 'Footer Tagline', '{"text":"Official moon-sighting announcements, reports and Islamic calendar information for communities across Great Britain and Europe."}', '{"text":"Official moon-sighting announcements, reports and Islamic calendar information for communities across Great Britain and Europe."}', 'System', unixepoch());
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('committee-intro', 'Committee Page Intro', '{"text":"The committee brings together scholars, astronomical advisers and regional representatives across Great Britain and Europe. Member details are published here only once approved by administrators."}', '{"text":"The committee brings together scholars, astronomical advisers and regional representatives across Great Britain and Europe. Member details are published here only once approved by administrators."}', 'System', unixepoch());
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('moon-sighting-intro', 'Moon Sighting Page Intro', '{"text":"A real-time view of where the committee''s review process stands, and how sighting reports are distributed across our regional network."}', '{"text":"A real-time view of where the committee''s review process stands, and how sighting reports are distributed across our regional network."}', 'System', unixepoch());
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('contact-intro', 'Contact Page Intro', '{"text":"Questions about a sighting, an announcement, or how to get involved? Reach us through the channels below."}', '{"text":"Questions about a sighting, an announcement, or how to get involved? Reach us through the channels below."}', 'System', unixepoch());
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('privacy-policy', 'Privacy Policy', '{"updated":"Draft — not yet finalised","body":"## Information We Collect\nWhen you submit a moon-sighting report, contact us, or subscribe to updates, we may collect information such as your name, contact details, general or exact location, and details of your observation, including any photographs you choose to upload.\n\n## How We Use Your Information\nInformation submitted through the sighting report form is used solely to review and verify moon-sighting observations as part of the committee''s decision-making process. Contact details may be used to follow up on a report for verification purposes.\n\n## Data Retention\nReports and associated information are retained for a period necessary to support the committee''s records and historical archive, after which they may be anonymised or deleted in line with the committee''s data retention schedule (to be defined).\n\n## Sharing of Information\nPersonal information submitted in a sighting report is not published publicly. Only aggregated or anonymised information (such as regional summaries) may appear on public-facing pages of this website.\n\n## Your Rights\nYou may request access to, correction of, or deletion of personal information you have submitted by contacting the committee using the details on the Contact page.\n\n## Contact\nQuestions about this policy can be directed to the committee via the Contact page once official contact details are confirmed."}', '{"updated":"Draft — not yet finalised","body":"## Information We Collect\nWhen you submit a moon-sighting report, contact us, or subscribe to updates, we may collect information such as your name, contact details, general or exact location, and details of your observation, including any photographs you choose to upload.\n\n## How We Use Your Information\nInformation submitted through the sighting report form is used solely to review and verify moon-sighting observations as part of the committee''s decision-making process. Contact details may be used to follow up on a report for verification purposes.\n\n## Data Retention\nReports and associated information are retained for a period necessary to support the committee''s records and historical archive, after which they may be anonymised or deleted in line with the committee''s data retention schedule (to be defined).\n\n## Sharing of Information\nPersonal information submitted in a sighting report is not published publicly. Only aggregated or anonymised information (such as regional summaries) may appear on public-facing pages of this website.\n\n## Your Rights\nYou may request access to, correction of, or deletion of personal information you have submitted by contacting the committee using the details on the Contact page.\n\n## Contact\nQuestions about this policy can be directed to the committee via the Contact page once official contact details are confirmed."}', 'System', unixepoch());
INSERT OR IGNORE INTO content_blocks (id, label, draft_fields, published_fields, updated_by_name, published_at) VALUES ('terms-of-use', 'Terms of Use', '{"updated":"Draft — not yet finalised","body":"## Acceptance of Terms\nBy accessing or using this website, you agree to these terms of use. If you do not agree, please do not use the website.\n\n## Nature of Announcements\nContent published on this website, including moon-sighting announcements and calendar information, reflects the decisions and processes of the Central Moon Sighting Committee GB & EU. Astronomical estimates shown on the calendar are informational only and are not official religious rulings.\n\n## Submitting a Sighting Report\nBy submitting a sighting report, you confirm that the information provided is truthful and accurate to the best of your knowledge. Submission of a report does not itself constitute an official moon-sighting declaration.\n\n## Acceptable Use\nYou agree not to submit false or misleading reports, attempt to disrupt the operation of this website, or use it for any unlawful purpose.\n\n## Limitation of Liability\nThis website and its content are provided on an as-is basis. The committee is not liable for decisions made in reliance on information published here, to the extent permitted by law.\n\n## Changes to These Terms\nThese terms may be updated from time to time. Continued use of the website after changes are published constitutes acceptance of the updated terms."}', '{"updated":"Draft — not yet finalised","body":"## Acceptance of Terms\nBy accessing or using this website, you agree to these terms of use. If you do not agree, please do not use the website.\n\n## Nature of Announcements\nContent published on this website, including moon-sighting announcements and calendar information, reflects the decisions and processes of the Central Moon Sighting Committee GB & EU. Astronomical estimates shown on the calendar are informational only and are not official religious rulings.\n\n## Submitting a Sighting Report\nBy submitting a sighting report, you confirm that the information provided is truthful and accurate to the best of your knowledge. Submission of a report does not itself constitute an official moon-sighting declaration.\n\n## Acceptable Use\nYou agree not to submit false or misleading reports, attempt to disrupt the operation of this website, or use it for any unlawful purpose.\n\n## Limitation of Liability\nThis website and its content are provided on an as-is basis. The committee is not liable for decisions made in reliance on information published here, to the extent permitted by law.\n\n## Changes to These Terms\nThese terms may be updated from time to time. Continued use of the website after changes are published constitutes acceptance of the updated terms."}', 'System', unixepoch());

